from datetime import date, timedelta


def cleanup_upcoming_jobs(apps, schema_editor):
    Job = apps.get_model('jobs', 'Job')
    SkippedRecruitment = apps.get_model('jobs', 'SkippedRecruitment')

    today = date.today()
    upcoming_jobs = Job.objects.filter(is_upcoming=True)

    for job in upcoming_jobs:
        url = (job.verification_url or job.original_url or '').strip().rstrip('/')
        if not url:
            job.delete()
            continue

        start_date = job.application_start_date
        recheck_date = start_date if (start_date and start_date > today) else (today + timedelta(days=1))

        SkippedRecruitment.objects.update_or_create(
            url=url,
            defaults={
                'title': job.title or 'Upcoming Recruitment Notice',
                'reason': f"Upcoming form not live yet (Starts: {start_date or 'Available Soon'})",
                'application_deadline': job.application_deadline,
                'recheck_after': recheck_date,
            }
        )
        job.delete()


